package com.moodcanvas.servlet;
import com.moodcanvas.dao.*;import com.moodcanvas.model.User;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;
public class AdminServlet extends HttpServlet {private static final long serialVersionUID=1L;protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{HttpSession x=q.getSession(false);if(x==null||!(x.getAttribute("user") instanceof User)||!"admin".equals(x.getAttribute("role"))){s.sendRedirect(q.getContextPath()+"/pages/dashboard.jsp");return;}try{UserDAO u=new UserDAO();MoodDAO m=new MoodDAO();JournalDAO j=new JournalDAO();q.setAttribute("userCount",u.count());q.setAttribute("moodCount",m.count());q.setAttribute("journalCount",j.count());q.setAttribute("users",u.getAll());q.setAttribute("moods",m.getAll());q.getRequestDispatcher("/pages/admin.jsp").forward(q,s);}catch(Exception e){q.getRequestDispatcher("/pages/error.jsp").forward(q,s);}}}
